   module Prob_6_35g_Ripple_Counter_4bit_a (output [3: 0] A,  input Count, reset_b);     reg A0, A1, A2, A3;     assign A = {A3, A2, A1, A0};     always @ (negedge Count, negedge reset_b)       if (reset_b == 0) A0 <= 0; else if (Count) A0 <= ~A0;         always @ (negedge A0, negedge reset_b)       if (reset_b == 0) A1 <= 0; else if (Count) A1 <= ~A1;         always @ (negedge A1, negedge reset_b)       if (reset_b == 0) A2 <= 0; else if (Count) A2 <= ~A2;        always @ (negedge A2, negedge reset_b)       if (reset_b == 0) A3 <= 0; else if (Count) A3 <= ~A3;   endmodule